#!/usr/bin/env python3
"""Generates src/cloud/mega/account/keys_vectors.rs with an implementation that
is independent from the Rust code under test (Python standard library +
`cryptography`).

Covers what the key-manager work needs:

* AES-128-GCM (96 bit nonce, 16 byte tag, no AAD) of several lengths.
* The `^!keys` key: HKDF-SHA256(ikm = master key, salt = none, info = 0x01),
  16 bytes.
* The `^!keys` container: records `tag(1) || length(3, big endian) || body`;
  a stored value is `0x14 0x00 || nonce(12) || AES-GCM(plain)`. The sample
  container has every known record plus two records with tags no client here
  knows (they must survive any edit untouched). Expected containers after
  "add a share key" and "set a flag" are built here by plain byte surgery:
  generation + 1, only the share key record changed. Share key entries are
  `handle(6) || key(16) || flags(1)`.
* Copy: a node's key for the copy is the same for files and fresh for folders
  (so only the file side is fixed); `k` is AES-ECB(master, key) and `a` is the
  node's attributes without `rr`, sealed (zero-IV CBC of `MEGA` + compact
  JSON, zero padded).
* Import of a public folder link: every node `k` is `<owner>:<b64
  AES-ECB(folder key, node key)>`; after import a file keeps its key wrapped
  with the master key.
* Import of a public file link: `k` = AES-ECB(master, file key), `a` = the
  link's sealed attributes.

Usage: python3 -I generate_keys_vectors.py > ../../../src/cloud/mega/account/keys_vectors.rs
All inputs are fixed (derived from a counter), so the output is reproducible.
"""
import base64
import json
import struct
import sys

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF


def det(label: str, length: int) -> bytes:
    """Deterministic pseudo random bytes (SHA-256 counter stream)."""
    import hashlib

    out = b""
    counter = 0
    while len(out) < length:
        out += hashlib.sha256(f"{label}/{counter}".encode()).digest()
        counter += 1
    return out[:length]


def b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode().rstrip("=")


def ecb_enc(key, data):
    e = Cipher(algorithms.AES(key), modes.ECB()).encryptor()
    return e.update(data) + e.finalize()


def cbc_enc_zero_iv(key, data):
    e = Cipher(algorithms.AES(key), modes.CBC(bytes(16))).encryptor()
    return e.update(data) + e.finalize()


def fold(file_key: bytes) -> bytes:
    return bytes(a ^ b for a, b in zip(file_key[:16], file_key[16:]))


def seal_attrs(aes_key: bytes, attributes: dict) -> str:
    text = json.dumps(attributes, separators=(",", ":"), sort_keys=True, ensure_ascii=False)
    raw = b"MEGA" + text.encode()
    raw += bytes(-len(raw) % 16)
    return b64(cbc_enc_zero_iv(aes_key, raw))


def rec(tag: int, body: bytes) -> bytes:
    assert len(body) < 1 << 24
    return bytes([tag]) + len(body).to_bytes(3, "big") + body


def rust_bytes(data: bytes) -> str:
    return "[" + ", ".join(f"0x{b:02x}" for b in data) + "]"


def rust_slice(data: bytes) -> str:
    return "&" + rust_bytes(data)


out = [
    "// @generated by tests/fixtures/mega/generate_keys_vectors.py -- do not edit.",
    "// Independent (Python `cryptography`) vectors for MEGA's ^!keys container, copy and import.",
    "",
]


def const(name: str, rust_type: str, value: str):
    out.append(f"pub const {name}: {rust_type} = {value};")


# ---- GCM ---------------------------------------------------------------------
gcm_cases = []
for index, length in enumerate([0, 1, 15, 16, 17, 31, 32, 33, 100, 300]):
    key = det(f"gcm-key/{index}", 16)
    nonce = det(f"gcm-nonce/{index}", 12)
    plain = det(f"gcm-plain/{index}", length)
    sealed = AESGCM(key).encrypt(nonce, plain, None)
    assert len(sealed) == length + 16
    gcm_cases.append((key, nonce, plain, sealed))
out.append("pub const GCM_CASES: &[([u8; 16], [u8; 12], &[u8], &[u8])] = &[")
for key, nonce, plain, sealed in gcm_cases:
    out.append(f"    ({rust_bytes(key)}, {rust_bytes(nonce)}, {rust_slice(plain)}, {rust_slice(sealed)}),")
out.append("];")

# ---- key derivation ------------------------------------------------------------
master = det("keys-master", 16)
derived = HKDF(algorithm=hashes.SHA256(), length=16, salt=None, info=bytes([1])).derive(master)
const("KEYS_MASTER", "[u8; 16]", rust_bytes(master))
const("KEYS_DERIVED", "[u8; 16]", rust_bytes(derived))

# ---- the container -------------------------------------------------------------
user_handle = det("keys-user", 8)
const("KEYS_USER_HANDLE", "&str", f'"{b64(user_handle)}"')
const("KEYS_IDENTITY", "[u8; 8]", rust_bytes(user_handle))

share_a = (det("keys-share-a-handle", 6), det("keys-share-a-key", 16), 0b11)
share_b = (det("keys-share-b-handle", 6), det("keys-share-b-key", 16), 0b01)


def entries(items):
    return b"".join(h + k + bytes([f]) for h, k, f in items)


GENERATION = 7
unknown_one = rec(0x7F, det("unknown-one", 37))
unknown_two = rec(0xC0, det("unknown-two", 5))


def container(generation: int, shares) -> bytes:
    return (
        rec(1, bytes([1]))
        + rec(2, struct.pack(">I", 1_700_000_000))
        + rec(3, user_handle)
        + rec(4, struct.pack(">I", generation))
        + rec(5, det("keys-attr", 9))
        + rec(16, det("keys-ed25519", 32))
        + rec(17, det("keys-cu25519", 32))
        + rec(18, det("keys-rsa", 600))
        + rec(32, det("keys-authring-ed", 41))
        + rec(33, det("keys-authring-cu", 23))
        + rec(48, entries(shares))
        + rec(64, det("keys-pending-out", 30))
        + rec(65, det("keys-pending-in", 52))
        + rec(80, det("keys-backups", 11))
        + rec(96, det("keys-warnings", 14))
        + unknown_one
        + unknown_two
    )


plain = container(GENERATION, [share_a, share_b])
nonce_one = det("keys-nonce-one", 12)
nonce_two = det("keys-nonce-two", 12)
nonce_three = det("keys-nonce-three", 12)
header = bytes([20, 0])
stored = header + nonce_one + AESGCM(derived).encrypt(nonce_one, plain, None)
const("CONTAINER_PLAIN", "&[u8]", rust_slice(plain))
const("CONTAINER_STORED", "&[u8]", rust_slice(stored))
const("CONTAINER_GENERATION", "u32", str(GENERATION))
const("CONTAINER_SHARE_COUNT", "usize", "2")
const("CONTAINER_RECORD_COUNT", "usize", "17")

added = (det("keys-added-handle", 6), det("keys-added-key", 16), 0b01)
plain_added = container(GENERATION + 1, [share_a, share_b, added])
stored_added = header + nonce_two + AESGCM(derived).encrypt(nonce_two, plain_added, None)
const("ADDED_HANDLE", "[u8; 6]", rust_bytes(added[0]))
const("ADDED_KEY", "[u8; 16]", rust_bytes(added[1]))
const("ADDED_FLAGS", "u8", str(added[2]))
const("ADDED_NONCE", "[u8; 12]", rust_bytes(nonce_two))
const("CONTAINER_ADDED_PLAIN", "&[u8]", rust_slice(plain_added))
const("CONTAINER_ADDED_STORED", "&[u8]", rust_slice(stored_added))

# flags: the second share key (trusted only) becomes trusted + in use.
flagged_b = (share_b[0], share_b[1], 0b11)
plain_flagged = container(GENERATION + 1, [share_a, flagged_b])
stored_flagged = header + nonce_three + AESGCM(derived).encrypt(nonce_three, plain_flagged, None)
const("FLAG_HANDLE", "[u8; 6]", rust_bytes(share_b[0]))
const("FLAG_NEW", "u8", str(flagged_b[2]))
const("FLAG_NONCE", "[u8; 12]", rust_bytes(nonce_three))
const("CONTAINER_FLAGGED_PLAIN", "&[u8]", rust_slice(plain_flagged))
const("CONTAINER_FLAGGED_STORED", "&[u8]", rust_slice(stored_flagged))
const("SHARE_A_HANDLE", "[u8; 6]", rust_bytes(share_a[0]))
const("SHARE_A_KEY", "[u8; 16]", rust_bytes(share_a[1]))
const("UNKNOWN_RECORDS", "&[u8]", rust_slice(unknown_one + unknown_two))

# ---- copy ------------------------------------------------------------------------
copy_master = det("copy-master", 16)
file_key = det("copy-file-key", 32)
file_attrs = {"c": "FINGERPRINT", "n": "report.pdf", "rr": "RESTORE1"}
clean_attrs = {k: v for k, v in file_attrs.items() if k != "rr"}
const("COPY_MASTER", "[u8; 16]", rust_bytes(copy_master))
const("COPY_FILE_KEY", "[u8; 32]", rust_bytes(file_key))
const("COPY_FILE_ATTRS_JSON", "&str", 'r####"' + json.dumps(file_attrs, separators=(",", ":"), sort_keys=True) + '"####')
const("COPY_FILE_K", "&str", f'"{b64(ecb_enc(copy_master, file_key))}"')
const("COPY_FILE_A", "&str", f'"{seal_attrs(fold(file_key), clean_attrs)}"')
folder_key_old = det("copy-folder-key", 16)
const("COPY_FOLDER_KEY", "[u8; 16]", rust_bytes(folder_key_old))

# ---- import ------------------------------------------------------------------------
imp_master = det("import-master", 16)
imp_folder_key = det("import-folder-key", 16)
root_key = det("import-root-key", 16)
sub_key = det("import-sub-key", 16)
imp_file_key = det("import-file-key", 32)
imp_file2_key = det("import-file2-key", 32)
nodes = [
    # handle, parent, type, key, attributes, size
    ("IMPROOT1", "", 1, root_key, {"n": "Shared"}, None),
    ("IMPSUB01", "IMPROOT1", 1, sub_key, {"n": "docs"}, None),
    ("IMPFILE1", "IMPSUB01", 0, imp_file_key, {"n": "paper.txt", "c": "FP-ONE"}, 1234),
    ("IMPFILE2", "IMPROOT1", 0, imp_file2_key, {"n": "top.bin"}, 99),
]
listing_nodes = []
for handle, parent, kind, key, attrs, size in nodes:
    akey = key if kind == 1 else fold(key)
    node = {
        "h": handle,
        "p": parent or "NOPARENT",
        "t": kind,
        "k": f"IMPROOT1:{b64(ecb_enc(imp_folder_key, key))}",
        "a": seal_attrs(akey, attrs),
        "ts": 1_600_000_000,
    }
    if size is not None:
        node["s"] = size
    listing_nodes.append(node)
listing = {"f": listing_nodes}
const("IMPORT_MASTER", "[u8; 16]", rust_bytes(imp_master))
const("IMPORT_FOLDER_KEY", "[u8; 16]", rust_bytes(imp_folder_key))
const("IMPORT_LISTING", "&str", 'r####"' + json.dumps(listing, separators=(",", ":")) + '"####')
const("IMPORT_FILE1_KEY", "[u8; 32]", rust_bytes(imp_file_key))
const("IMPORT_FILE1_K", "&str", f'"{b64(ecb_enc(imp_master, imp_file_key))}"')
const("IMPORT_FILE1_A", "&str", f'"{seal_attrs(fold(imp_file_key), {"c": "FP-ONE", "n": "paper.txt"})}"')
const("IMPORT_FILE2_K", "&str", f'"{b64(ecb_enc(imp_master, imp_file2_key))}"')
const("IMPORT_FILE2_A", "&str", f'"{seal_attrs(fold(imp_file2_key), {"n": "top.bin"})}"')

link_file_key = det("link-file-key", 32)
link_attrs = {"n": "linked.iso", "c": "FP-LINK"}
const("LINK_FILE_KEY", "[u8; 32]", rust_bytes(link_file_key))
const("LINK_FILE_AT", "&str", f'"{seal_attrs(fold(link_file_key), link_attrs)}"')
const("LINK_FILE_K", "&str", f'"{b64(ecb_enc(imp_master, link_file_key))}"')

# self checks: decrypt everything again
assert AESGCM(derived).decrypt(nonce_one, stored[14:], None) == plain
assert len(plain_added) == len(plain) + 23
assert plain_flagged != plain and len(plain_flagged) == len(plain)
sys.stdout.write("\n".join(out) + "\n")
